'use strict';
const $=id=>document.getElementById(id),fmt=(n,d=2)=>n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});let mode='price',current;
function read(){return {face:+$('face').value,coupon:+$('coupon').value,years:+$('years').value,frequency:+$('frequency').value};}
function calc(){try{const b=read();if(!$('inputs').checkValidity())throw Error('Please complete the inputs within the stated limits.');const y=mode==='price'?+$('yield').value:BondMath.ytm(b,+$('market').value);const v=BondMath.value(b,y);if(!Number.isFinite(v.price))throw Error('These inputs exceed the numeric range.');current={b,y,v};$('error').textContent='';$('results').style.opacity=1;$('price').textContent=mode==='price'?fmt(v.price):fmt(y,3)+'%';$('resultTitle').textContent=mode==='price'?'THEORETICAL BOND PRICE':'IMPLIED YIELD TO MATURITY';$('priceSub').textContent=mode==='price'?fmt(v.price/b.face*100)+' per 100 of face value':'At a market price of '+fmt(v.price);$('ytm').textContent=fmt(y,3)+'%';$('duration').textContent=fmt(v.duration)+' yrs';$('modified').textContent=fmt(v.modified);const diff=v.price-b.face;$('status').textContent=Math.abs(diff)<.005?'AT PAR':diff<0?'BELOW PAR':'ABOVE PAR';$('insight').textContent=Math.abs(diff)<.005?'Coupon and yield match, so the bond trades at face value.':diff<0?'The coupon rate is below the required yield. A lower price makes up the difference.':'The coupon rate exceeds the required yield. Those larger payments command a premium.';$('step1').textContent=`${fmt(b.face)} × ${fmt(b.coupon)}% ÷ ${b.frequency} = ${fmt(v.couponPayment)} each period. There are ${v.flows.length} payments; the final payment includes ${fmt(b.face)} of principal.`;$('step2').textContent=`The periodic yield is ${fmt(y,3)}% ÷ ${b.frequency} = ${fmt(y/b.frequency,4)}%. For period 1: ${fmt(v.flows[0].cash)} ÷ (1 + ${fmt(y/100/b.frequency,6)})¹ = ${fmt(v.flows[0].pv)}.`;$('step3').textContent=`Present value of coupons: ${fmt(v.price-b.face*(1+y/100/b.frequency)**(-v.flows.length))}. Present value of principal: ${fmt(b.face*(1+y/100/b.frequency)**(-v.flows.length))}. Together: ${fmt(v.price)}.${mode==='yield'?' The solver varies yield until this sum matches your market price.':''}`;$('flows').innerHTML=v.flows.map(f=>`<tr><td>${f.period}</td><td>${fmt(f.time,3)}</td><td>${fmt(f.cash)}</td><td>${fmt(f.factor,6)}</td><td>${fmt(f.pv)}</td></tr>`).join('');$('convexity').textContent=`Convexity for this bond: ${fmt(v.convexity,4)} years². Values use full precision internally; displayed values are rounded.`;chart();shock();}catch(e){current=null;$('error').textContent=e.message;$('results').style.opacity=.4;}}
function chart(){const {b,y,v}=current;const low=Math.max(y-3,-99*b.frequency),high=y+3,pts=Array.from({length:61},(_,i)=>{const rate=low+i*(high-low)/60;return [rate,BondMath.value(b,rate).price];});const min=pts[60][1]*.98,max=pts[0][1]*1.02,x=a=>65+(a-low)/(high-low)*630,z=a=>195-(a-min)/(max-min)*170;let s='';for(let i=0;i<4;i++){const val=min+(max-min)*i/3;s+=`<line x1="65" y1="${z(val)}" x2="695" y2="${z(val)}" stroke="#e5eade"/><text x="54" y="${z(val)+4}" text-anchor="end">${fmt(val,0)}</text>`;}for(let i=0;i<=6;i++)s+=`<text x="${x(low+i*(high-low)/6)}" y="216" text-anchor="middle">${fmt(low+i*(high-low)/6,1)}%</text>`;const path=pts.map((p,i)=>(i?'L':'M')+x(p[0])+','+z(p[1])).join(' ');s+=`<path d="${path} L695,195 L65,195 Z" fill="#eaf1dc" opacity=".6"/><path d="${path}" fill="none" stroke="#275e46" stroke-width="2.5"/><line x1="${x(y)}" x2="${x(y)}" y1="${z(v.price)}" y2="195" stroke="#8ca66c" stroke-dasharray="4 4"/><circle cx="${x(y)}" cy="${z(v.price)}" r="5" fill="#275e46" stroke="white" stroke-width="2"/><text x="380" y="238" text-anchor="middle">Annual yield to maturity</text>`;$('chart').innerHTML=s;}
function shock(){if(!current)return;const {b,y,v}=current,d=+$('shock').value;if(y+d<=-100*b.frequency){$('shockText').textContent='This change would give a non-positive discount factor. Choose a higher yield.';return;}const p=BondMath.value(b,y+d).price,change=(p/v.price-1)*100,approx=-v.modified*d;$('shockLabel').textContent=(d>=0?'+':'')+fmt(d)+' pp';$('shockText').textContent=`At ${fmt(y+d)}% yield, price becomes ${fmt(p)} (${change>=0?'+':''}${fmt(change)}%). Duration alone estimates ${approx>=0?'+':''}${fmt(approx)}%. Full repricing captures the curve.`;}
function setMode(m){mode=m;$('yieldLabel').hidden=m==='yield';$('yield').disabled=m==='yield';$('marketLabel').hidden=m==='price';$('market').disabled=m==='price';for(const k of ['price','yield']){$(k+'Mode').classList.toggle('active',k===m);$(k+'Mode').setAttribute('aria-pressed',k===m);}calc();}
$('inputs').onsubmit=e=>{e.preventDefault();calc();};$('priceMode').onclick=()=>setMode('price');$('yieldMode').onclick=()=>setMode('yield');$('shock').oninput=shock;
document.querySelectorAll('[data-example]').forEach(btn=>btn.onclick=()=>{const ex={discount:[5,5,6,2],premium:[7,5,4,2],zero:[0,5,5,1]}[btn.dataset.example];$('face').value=1000;['coupon','years','yield','frequency'].forEach((k,i)=>$(k).value=ex[i]);setMode('price');});
$('export').onclick=()=>{if(!current)return;const rows=['Period,Year,Cash flow,Discount factor,Present value',...current.v.flows.map(f=>[f.period,f.time,f.cash,f.factor,f.pv].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='bondlab-cash-flows.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};setMode('price');
